30	public class ContainerMerkleTreeMetrics {
31	  private static final String METRICS_SOURCE_NAME = ContainerMerkleTreeMetrics.class.getSimpleName();
32	
33	  public static ContainerMerkleTreeMetrics create() {
34	    MetricsSystem ms = DefaultMetricsSystem.instance();
35	    MetricsSource source = ms.getSource(METRICS_SOURCE_NAME);
36	    if (source != null) {
37	      ms.unregisterSource(METRICS_SOURCE_NAME);
38	    }
39	    return ms.register(METRICS_SOURCE_NAME, "Container Merkle Tree Metrics",
40	        new ContainerMerkleTreeMetrics());
41	  }
42	
43	  public static void unregister() {
44	    MetricsSystem ms = DefaultMetricsSystem.instance();
45	    ms.unregisterSource(METRICS_SOURCE_NAME);
46	  }
