package org.apache.hadoop.ozone.container.checksum;

import org.apache.hadoop.hdds.protocol.datanode.proto.ContainerProtos.BlockMerkleTree;
import org.apache.hadoop.hdds.protocol.datanode.proto.ContainerProtos.ChunkMerkleTree;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * This class represents the difference between our replica of a container and a peer's replica of a container.
 * It summarizes the operations we need to do to reconcile our replica with the peer's replica it was compared to.
 * The differences are captured from the perspective of the local container replica. It contains:
 * - Blocks that are present in the peer's replica but missing from our replica.
 * - Chunks that are present in the peer's replica but missing from our replica for a block present in both replicas.
 * - Chunks that are present in both replicas but are corrupt in our replica.
 */
public class ContainerDiffReport {

  // List of blocks that are present in the peer's replica but missing from our replica.
  private final List<BlockMerkleTree> missingBlocks;
  // Map of blockId to the list of chunks that are present in the peer's replica but missing from our replica.
  private final Map<Long, List<ChunkMerkleTree>> missingChunks;
  // Map of blockId to the list of chunks that are corrupt in our replica but healthy in the peer's replica.
  private final Map<Long, List<ChunkMerkleTree>> corruptChunks;

  public ContainerDiffReport() {
    this.missingBlocks = new ArrayList<>();
    this.missingChunks = new HashMap<>();
    this.corruptChunks = new HashMap<>();
  }

  public void addMissingBlock(BlockMerkleTree missingBlockMerkleTree) {
    this.missingBlocks.add(missingBlockMerkleTree);
  }

  public void addMissingChunk(long blockId, ChunkMerkleTree missingChunkMerkleTree) {
    this.missingChunks.computeIfAbsent(blockId, any -> new ArrayList<>()).add(missingChunkMerkleTree);
  }

  public void addCorruptChunk(long blockId, ChunkMerkleTree corruptChunkMerkleTree) {
    this.corruptChunks.computeIfAbsent(blockId, any -> new ArrayList<>()).add(corruptChunkMerkleTree);
  }

  public List<BlockMerkleTree> getMissingBlocks() {
    return missingBlocks;
  }

  public Map<Long, List<ChunkMerkleTree>> getMissingChunks() {
    return missingChunks;
  }

  public Map<Long, List<ChunkMerkleTree>> getCorruptChunks() {
    return corruptChunks;
  }

  public boolean needsRepair() {
    return !missingBlocks.isEmpty() || !missingChunks.isEmpty() || !corruptChunks.isEmpty();
  }
}
